// Independent seat check. Do NOT edit this file to make it pass; fix seatService instead.
// Run from server/:  node tests/seat.check.js     (needs MONGO_URI in server/.env; uses a throwaway DB, dropped at the end)
// Contract: holdSeats(showId, labels, userId), releaseSeats(showId, labels, userId),
//           confirmSeats(showId, labels, userId), cancelSeats(showId, labels). All return true/false.
const path = require('path');
require('dotenv').config({ path: path.join(__dirname, '..', '.env') });
const mongoose = require('mongoose');
const Show = require('../models/Show');
const seats = require('../services/seatService');

const oid = () => new mongoose.Types.ObjectId();
let failed = 0;
const check = (name, ok) => { console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}`); if (!ok) failed++; };

const newShow = () =>
  Show.create({
    movie: oid(), theatre: oid(), screenId: oid(), language: 'English',
    startTime: new Date(Date.now() + 6 * 3600e3),
    endTime: new Date(Date.now() + 8 * 3600e3),
    seats: ['A1', 'A2', 'A3', 'A4', 'A5', 'A6'].map((label, i) => ({
      label, row: 'A', number: i + 1, price: 200,
    })),
  });
const seat = async (id, label) => (await Show.findById(id).lean()).seats.find((s) => s.label === label);
const expire = (id, label) =>
  Show.updateOne(
    { _id: id },
    { $set: { 'seats.$[x].heldUntil': new Date(Date.now() - 1000) } },
    { arrayFilters: [{ 'x.label': label }] }
  );

(async () => {
  await mongoose.connect(process.env.MONGO_URI, { dbName: `imovies_check_${Date.now()}` });
  try {
    // 1. concurrency
    let s = await newShow();
    const res = await Promise.all(Array.from({ length: 20 }, () => seats.holdSeats(s._id, ['A1'], oid())));
    check('20 parallel holds of one seat: exactly 1 wins', res.filter((x) => x === true).length === 1);

    // 2. all-or-nothing
    s = await newShow();
    const x = oid(), y = oid();
    check('user X holds A2', (await seats.holdSeats(s._id, ['A2'], x)) === true);
    check('user Y holding [A2,A3] is rejected', (await seats.holdSeats(s._id, ['A2', 'A3'], y)) === false);
    check('A3 stayed available (no partial hold)', (await seat(s._id, 'A3')).status === 'available');

    // 3. unknown label
    s = await newShow();
    check('hold of nonexistent seat Z9 rejected', (await seats.holdSeats(s._id, ['Z9'], oid())) === false);
    check('hold of [A1,Z9] rejected and A1 untouched',
      (await seats.holdSeats(s._id, ['A1', 'Z9'], oid())) === false && (await seat(s._id, 'A1')).status === 'available');

    // 4. expired hold is free
    s = await newShow();
    await seats.holdSeats(s._id, ['A1'], oid());
    check('live hold blocks another user', (await seats.holdSeats(s._id, ['A1'], oid())) === false);
    await expire(s._id, 'A1');
    check('expired hold can be taken by another user', (await seats.holdSeats(s._id, ['A1'], oid())) === true);

    // 5. confirm
    s = await newShow();
    const owner = oid(), other = oid();
    await seats.holdSeats(s._id, ['A5', 'A6'], owner);
    check('non-owner cannot confirm', (await seats.confirmSeats(s._id, ['A5', 'A6'], other)) === false);
    check('owner confirms', (await seats.confirmSeats(s._id, ['A5', 'A6'], owner)) === true);
    check('A5 and A6 are booked', (await seat(s._id, 'A5')).status === 'booked' && (await seat(s._id, 'A6')).status === 'booked');
    check('booked seat cannot be held', (await seats.holdSeats(s._id, ['A5'], oid())) === false);

    // 6. confirm after expiry
    s = await newShow();
    const u6 = oid();
    await seats.holdSeats(s._id, ['A1'], u6);
    await expire(s._id, 'A1');
    check('confirm after hold expired fails', (await seats.confirmSeats(s._id, ['A1'], u6)) === false);

    // 7. release
    s = await newShow();
    const u7 = oid();
    await seats.holdSeats(s._id, ['A2'], u7);
    check('non-owner release changes nothing', (await seats.releaseSeats(s._id, ['A2'], oid())) === false && (await seat(s._id, 'A2')).status === 'held');
    check('owner release frees seat', (await seats.releaseSeats(s._id, ['A2'], u7)) === true && (await seat(s._id, 'A2')).status === 'available');

    // 8. cancel
    s = await newShow();
    const u8 = oid();
    await seats.holdSeats(s._id, ['A3'], u8);
    await seats.confirmSeats(s._id, ['A3'], u8);
    check('cancel of non-booked seat rejected', (await seats.cancelSeats(s._id, ['A4'])) === false);
    check('cancel frees booked seat', (await seats.cancelSeats(s._id, ['A3'])) === true && (await seat(s._id, 'A3')).status === 'available');
  } catch (e) {
    console.error('ERROR', e);
    failed++;
  } finally {
    await mongoose.connection.dropDatabase();
    await mongoose.disconnect();
    console.log(failed ? `\n${failed} FAILED` : '\nALL PASSED');
    process.exit(failed ? 1 : 0);
  }
})();
